func ListWorkflowsRegistration(tool *ListWorkflowsTool, logger logr.Logger) mcpinternal.ToolRegistration {
	return func(server *mcpsdk.Server, _ func(context.Context) mcpinternal.UserInfo) {
		mcpsdk.AddTool(server, &mcpsdk.Tool{
			Name:        "kubernaut_list_workflows",
			Description: "List available remediation workflows from the catalog, optionally filtered by resource kind",
		}, func(ctx context.Context, req *mcpsdk.CallToolRequest, input ListWorkflowsInput) (*mcpsdk.CallToolResult, ListWorkflowsOutput, error) {
			output, err := tool.Handle(ctx, input)
			return nil, output, ErrorBoundary(logger, "kubernaut_list_workflows", err)
		})
	}
}

func (t *SelectWorkflowTool) Handle(ctx context.Context, input SelectWorkflowInput, user mcpinternal.UserInfo) (SelectWorkflowOutput, error) {
	if err := validateSelectWorkflowInput(input); err != nil {
		return SelectWorkflowOutput{}, err
	}

	if t.mutexProvider != nil {
		mu := t.mutexProvider.GetSessionMutex(input.RRID)
		mu.Lock()
		defer mu.Unlock()
	}

	driver, driverErr := t.authorizeSelectionDriver(input, user)
	if driverErr != nil {
		return SelectWorkflowOutput{}, driverErr
	}

	backfillTargetFromRCA(&input, driver)

	pctx := &PreSelectionContext{SessionID: driver.SessionID}
	for _, hook := range t.preSelectionHooks {
		if err := hook(ctx, input, user, pctx); err != nil {
			return SelectWorkflowOutput{}, err
		}
	}

	workflow, err := t.catalog.GetWorkflowByID(ctx, input.WorkflowID)
	if err != nil {
		return SelectWorkflowOutput{}, fmt.Errorf("workflow catalog lookup failed: %w", err)
	}

	// #1654: stop the inactivity timer synchronously (not deferred to the
	// completion goroutine below) — the session is terminating regardless of
	// whether an HTTP completer is wired, so the timer must not be left
	// running to fire later against an already-terminal session.
	if t.timeoutTracker != nil {
		t.timeoutTracker.StopTracking(driver.SessionID)
	}

	// Auto-complete: build final InvestigationResult from RCA + selected workflow,
	// write to HTTP session store, and release the MCP lease. Deferred to a
	// goroutine so the tool response reaches the caller before session teardown
	// closes the transport (fixes "incomplete chunked read" in kagenti).
	t.completeSelectionAsync(input, driver, workflow)

	return SelectWorkflowOutput{
		Status:     "workflow_selected",
		Workflow:   workflow,
		Enrichment: pctx.Enrichment,
		Confidence: 1.0,
		Rationale:  "User-selected via interactive mode",
	}, nil
}

func (v *Validator) SetDiscoveredWorkflowState(state *katypes.DiscoveredWorkflowState) {
	v.discoveredWorkflows = state
}

func (v *Validator) GetWorkflowMeta(workflowID string) (WorkflowMeta, bool) {
	m, ok := v.catalogMeta[workflowID]
	return m, ok
}

// IsAllowed reports whether workflowID is present in the catalog allowlist and,
// when discovery state is attached, was returned by list_workflows in the
// current selection context. This
// is the same membership test Validate applies to workflow_id, exposed here
// so callers outside Validate (e.g. enrichFromCatalog's Issue #1711 guard)
// can distinguish "unresolvable ID" from "resolvable ID with no registered
// WorkflowMeta" -- the latter occurs only in test fixtures that populate the
// allowlist without a matching SetWorkflowMeta call; production always sets
// both from the same catalog-fetch loop (see dsCatalogFetcher.FetchValidator).
func (v *Validator) IsAllowed(workflowID string) bool {
	if _, ok := v.allowedWorkflows[workflowID]; !ok {
		return false
	}
	return v.discoveredWorkflows == nil || v.discoveredWorkflows.Contains(workflowID)
}

func (t *listActionsTool) Execute(ctx context.Context, args json.RawMessage) (string, error) {
	signal, err := signalFromContext(ctx, "listing action types")
	if err != nil {
		return "", err
	}

	var a struct {
		Page   string `json:"page"`
		Cursor string `json:"cursor"`
	}
	if err := json.Unmarshal(args, &a); err != nil {
		return "", fmt.Errorf("parsing args: %w", err)
	}

	filters := filtersFromSignal(signal)
	logr.FromContextOrDiscard(ctx).V(1).Info("list_available_actions: resolved component",
		"component", filters.Component, "remediation_id", signal.RemediationID)

	offset, limit := 0, defaultPaginationLimit
	if a.Page != "" && a.Cursor != "" {
		offset, limit = decodeCursor(a.Cursor)
	}

	if t.catalog == nil {
		return "", fmt.Errorf("listing action types: workflow catalog unavailable")
	}

	start := time.Now()
	entries, totalCount, err := t.catalog.ListActions(ctx, filters, offset, limit)
	durationMs := time.Since(start).Milliseconds()
	if err != nil {
		return "", fmt.Errorf("listing action types: %w", err)
	}

	t.emitAuditEvent(ctx, filters, totalCount, durationMs)

	resp := models.ActionTypeListResponse{
		ActionTypes: entries,
		Pagination: models.PaginationMetadata{
			TotalCount: totalCount,
			Offset:     offset,
			Limit:      limit,
			HasMore:    offset+limit < totalCount,
		},
	}
	data, err := json.Marshal(resp)
	if err != nil {
		return "", fmt.Errorf("marshaling action types response: %w", err)
	}
	return string(transformPagination(data)), nil
}

