func (h *AIAnalysisHandler) handleFailed(
	ctx context.Context,
	rr *remediationv1.RemediationRequest,
	ai *aianalysisv1.AIAnalysis,
) (ctrl.Result, error) {
	// BR-KA-197: Check NeedsHumanReview FIRST (takes precedence over WorkflowResolutionFailed)
	// This flag is set by KA when AI cannot produce a reliable result
	if ai.Status.GetReview().NeedsHumanReview {
		return h.handleHumanReviewRequired(ctx, rr, ai)
	}

	// BR-ORCH-036: Handle WorkflowResolutionFailed
	if ai.Status.Reason == "WorkflowResolutionFailed" {
		return h.handleWorkflowResolutionFailed(ctx, rr, ai)
	}

	// BR-ORCH-036 v3.0: Other failures (APIError, Timeout, MaxRetriesExceeded, etc.)
	// Create escalation notification and propagate failure to RR
	return h.propagateFailure(ctx, rr, ai)
}

// resolved from the DS workflow catalog at selection time. Deliberately
// NOT Required: unlike WorkflowID/WorkflowName/ActionType/Version/
// ExecutionBundle (whose upstream sources guarantee non-empty values),
// AIAnalysis legitimately persists a SelectedWorkflow with this field
// empty on its partial/degenerate paths (e.g. workflow-resolution
// failure, low-confidence preservation -- see
// preservePartialSelectedWorkflow/preserveLowConfidenceWorkflow in
// pkg/aianalysis/handlers/response_processor.go) before
// RemediationOrchestrator's validateSelectedWorkflow ever runs its own
// Go-level fail-closed check. Tightening this to Required+no-omitempty
// broke exactly that: an empty string is present-but-invalid against the
// Enum, not merely "missing" (#1661 Change 12 CI regression, confirmed
// against IT-AA-344-001 and three sibling suites -- 100go.co "validate
// at the right layer": RO's runtime check, not CRD admission, is the
// correct gate here).

func applyDependenciesToSpec(schema *models.WorkflowSchema, spec *rwv1alpha1.RemediationWorkflowSpec) {
	if schema.Dependencies == nil {
		return
	}
	deps := &rwv1alpha1.RemediationWorkflowDependencies{}
	for _, s := range schema.Dependencies.Secrets {
		deps.Secrets = append(deps.Secrets, rwv1alpha1.RemediationWorkflowResourceDependency{Name: s.Name})
	}
	for _, cm := range schema.Dependencies.ConfigMaps {
		deps.ConfigMaps = append(deps.ConfigMaps, rwv1alpha1.RemediationWorkflowResourceDependency{Name: cm.Name})
	}
	spec.Dependencies = deps
}

func buildWorkflowCatalogCache(infra *k8sInfra, logger logr.Logger) *workflowcatalog.LazyCatalog {
	lazy := workflowcatalog.NewLazyCatalog(logger)

	if infra == nil {
		logger.Error(nil, "K8s infrastructure unavailable -- workflow catalog cache cannot start and will never become "+
			"ready; this should never happen in a real deployment (KA always runs in-cluster); /readyz will report "+
			"not_ready until the pod is restarted with valid K8s connectivity")
		return lazy
	}

	scheme, err := workflowcatalog.NewScheme()
	if err != nil {
		logger.Error(err, "FATAL: failed to build workflow catalog scheme")
		os.Exit(1)
	}

	lazy.Start(func() (*workflowcatalog.Cache, context.CancelFunc, error) {
		return workflowcatalog.NewInformerCache(infra.kubeConfig, scheme, logger)
	})
	return lazy
}

func (r *Reconciler) logConsecutiveFailureThresholdReached(ctx context.Context, rr *remediationv1.RemediationRequest, failurePhase remediationv1.FailurePhase, logger logr.Logger) {
	if failurePhase == remediationv1.FailurePhaseBlocked {
		return
	}
	// Count consecutive failures BEFORE this one (current failure not yet recorded)
	consecutiveFailures := r.countConsecutiveFailures(ctx, rr.Spec.SignalFingerprint)
	// +1 for this failure (not yet in status)
	if consecutiveFailures+1 >= r.getConsecutiveFailureThreshold() {
		logger.Info("Consecutive failure threshold reached, future RRs will be blocked",
			"consecutiveFailures", consecutiveFailures+1,
			"threshold", r.getConsecutiveFailureThreshold(),
			"fingerprint", rr.Spec.SignalFingerprint,
		)
	}
}

// RunWorkflowDiscoveryFromRCA executes Phase 3 (workflow selection) using a
// structured RCA result. This reuses the exact autonomous Phase 3 pipeline
// (BuildPhase1Context + runWorkflowSelection) so that interactive and
// autonomous workflow discovery produce consistent results.
//
// F5/F6 (#1374): When the investigator has an enricher wired, this function
// resolves enrichment internally (pre-RCA + post-RCA re-enrichment), mirroring
// the autonomous Investigate() pipeline. The caller-provided enrichData is used
// as fallback only when the enricher is nil.

// FinalizeWorkflowResult applies post-Phase 3 processing to the workflow
// discovery result, mirroring the autonomous path in Investigate() L558-569.
// This ensures interactive discover_workflows results have the same
// completeness as autonomous results: severity backfill, detected labels,
// authoritative remediation target, and TARGET_RESOURCE_* parameters.
//
// enrichData may be nil when the interactive path lacks full enrichment (F5).
// All callees handle nil gracefully.
func FinalizeWorkflowResult(result *katypes.InvestigationResult, signal katypes.SignalContext, rcaResult *katypes.InvestigationResult, enrichData *enrichment.EnrichmentResult) {

func (inv *Investigator) runWorkflowSelection(ctx context.Context, signal katypes.SignalContext, rcaSummary string, enrichData *prompt.EnrichmentData, p1Ctx *prompt.Phase1Data, llmCtx LLMInvocationContext) (result *katypes.InvestigationResult, retErr error) {
	correlationID := llmCtx.CorrelationID
	// Apply signal label overrides (target_resource_kind / target_resource_name)
	// before attaching to context. This ensures workflow discovery tools
	// (list_available_actions, list_workflows) filter by the correct component.
	// Defense-in-depth for #1064/#1065: even if enrichment resolved a container
	// kind (e.g. Namespace), the label override corrects it for tool context.
	discoveredWorkflows := katypes.NewDiscoveredWorkflowState()
	ctx = katypes.WithDiscoveredWorkflowState(ctx, discoveredWorkflows)
	overriddenSignal := ApplySignalLabelOverrides(signal)
	ctx = katypes.WithSignalContext(ctx, overriddenSignal)
	inv.logger.Info("runWorkflowSelection: post-override signal",
		"component_gvk", overriddenSignal.ComponentGVK(),
		"resource_kind", overriddenSignal.ResourceKind,
		"resource_api_version", overriddenSignal.ResourceAPIVersion,
		"correlation_id", correlationID)

	wfPromptSignal := SignalToPrompt(signal)
	LogLabelOverrideOrRejection(inv.logger, signal, wfPromptSignal, correlationID, "workflow selection")
	systemPrompt, err := inv.builder.RenderWorkflowSelection(prompt.WorkflowSelectionInput{
		Signal:                          wfPromptSignal,
		RCASummary:                      rcaSummary,
		EnrichData:                      enrichData,
		Phase1:                          p1Ctx,
		ResolvedConfidenceThreshold:     inv.resolvedConfidenceThreshold,
		InconclusiveConfidenceThreshold: inv.inconclusiveConfidenceThreshold,
	})
	if err != nil {
		return nil, fmt.Errorf("rendering workflow selection prompt: %w", err)
	}
	llmCtx.WorkflowDiscovery = newWorkflowDiscoveryAuditContext(enrichData, overriddenSignal, systemPrompt)

	messages := []llm.Message{
		{Role: "system", Content: systemPrompt},
		{Role: "user", Content: fmt.Sprintf("RCA findings: %s\n\nSelect the appropriate remediation workflow.", rcaSummary)},
	}

	loopRes, err := inv.runLLMLoop(ctx, messages, katypes.PhaseWorkflowDiscovery, llmCtx)
	if err != nil {
		return nil, err
	}
	// #1935/#1936 root cause #2 (workflow-discovery extension, #1945):
	// runLLMLoop's accumulated tool-call history must flow back into
	// messages before it feeds handleWorkflowSelectionLoopResult (and, via
	// it, retryWorkflowSubmit's two call sites and selfCorrectWorkflowSelection
	// below) — otherwise every retry/self-correction attempt operates on a
	// stale [system, user]-only slice regardless of how many
	// list_available_actions/list_workflows calls actually ran.
	if extended := loopResultMessages(loopRes); len(extended) > 0 {
		messages = extended
	}

	content, early := inv.handleWorkflowSelectionLoopResult(ctx, loopRes, rcaSummary, messages, llmCtx)
	if early != nil {
		return early, nil
	}

	result, parseErr := inv.resultParser.Parse(content)
	if parseErr != nil {
		var terminal *katypes.InvestigationResult
		content, terminal = inv.workflowSelectionRetryOrHumanReview(ctx, content, messages, rcaSummary, llmCtx, parseErr,
			fmt.Sprintf("workflow selection: LLM did not produce parseable result: %s", parseErr))
		if terminal != nil {
			return terminal, nil
		}
		// Genuine workflow selection recovered via retryWorkflowSubmit: fall
		// through into the same CatalogFetcher / selfCorrectWorkflowSelection
		// validation path below, exactly like a first-attempt success.
		// Returning it directly here would bypass catalog validation for
		// this specific retry path (#1677 follow-up hardening).
		result, parseErr = inv.resultParser.Parse(content)
		if parseErr != nil {
			return nil, fmt.Errorf("workflow selection: re-parsing retry-recovered content: %w", parseErr)
		}
	}

	// #1677 hardening (DD-WORKFLOW-019): CatalogFetcher is always configured
	// in production (cmd/kubernautagent always wires a workflowCatalogFetcher
	// backed by a LazyCatalog, ready or not) -- a nil CatalogFetcher here is
	// a test/wiring gap, not a supported "dev mode" that should silently
	// bypass validation. result.HumanReviewNeeded already true means the
	// parser/LLM itself determined no workflow selection needs validating
	// (e.g. no_matching_workflows) -- that classification is preserved
	// as-is, matching selfCorrectWorkflowSelection's own contract of only
	// running validation when there is an actual selection to validate.
	// Otherwise (a workflow WAS selected) failing closed instead of
	// returning it unvalidated mirrors selfCorrectWorkflowSelection's own
	// fetchErr handling below, so both "no fetcher configured" and "fetcher
	// configured but catalog not ready/unreachable" produce the same
	// observable outcome: human review, never silent pass-through.
	if inv.pipeline.CatalogFetcher == nil {
		if result.HumanReviewNeeded {
			return result, nil
		}
		inv.logger.Error(nil, "workflow catalog fetcher not configured, requiring human review instead of skipping validation",
			"correlation_id", correlationID)
		result.HumanReviewNeeded = true
		result.HumanReviewReason = "catalog_unavailable"
		result.Reason = "workflow catalog fetcher not configured"
		return result, nil
	}
	return inv.selfCorrectWorkflowSelection(ctx, result, content, messages, rcaSummary, correlationID, llmCtx)
}

func (inv *Investigator) selfCorrectWorkflowSelection(ctx context.Context, result *katypes.InvestigationResult, content string, messages []llm.Message, rcaSummary, correlationID string, llmCtx LLMInvocationContext) (*katypes.InvestigationResult, error) {
	validator, fetchErr := inv.pipeline.CatalogFetcher.FetchValidator(ctx)
	if fetchErr != nil {
		inv.logger.Error(fetchErr, "workflow catalog unavailable, requiring human review")
		result.HumanReviewNeeded = true
		result.HumanReviewReason = "catalog_unavailable"
		result.Reason = fmt.Sprintf("workflow catalog unavailable: %s", fetchErr)
		return result, nil
	}
	if discoveredWorkflows, ok := katypes.DiscoveredWorkflowStateFromContext(ctx); ok {
		validator.SetDiscoveredWorkflowState(discoveredWorkflows)
	}

	state := &selfCorrectionState{content: content, messages: messages}
	correctionFn := func(r *katypes.InvestigationResult, validationErr error) (*katypes.InvestigationResult, error) {
		return inv.runSelfCorrectionAttempt(ctx, r, validationErr, state, rcaSummary, correlationID, llmCtx)
	}

	corrected, corrErr := validator.SelfCorrect(result, maxSelfCorrectionAttempts, correctionFn)
	if corrErr != nil {
		return handleSelfCorrectError(corrErr, rcaSummary)
	}
	return inv.finalizeSelfCorrection(ctx, corrected, state.attempt, correlationID, validator), nil
}

func (inv *Investigator) runSelfCorrectionAttempt(ctx context.Context, r *katypes.InvestigationResult, validationErr error, state *selfCorrectionState, rcaSummary, correlationID string, llmCtx LLMInvocationContext) (*katypes.InvestigationResult, error) {
	state.attempt++
	var errStrs []string
	if validationErr != nil {
		errStrs = []string{validationErr.Error()}
	}
	inv.emitValidationEvent(ctx, state.attempt, maxSelfCorrectionAttempts, false, errStrs, r.WorkflowID, correlationID)

	correctionMsg, renderErr := inv.renderCorrectionMessage(validationErr, state.attempt, maxSelfCorrectionAttempts)
	if renderErr != nil {
		inv.logger.Error(renderErr, "failed to render validation error template, using fallback")
		correctionMsg = fmt.Sprintf("Validation failed: %s. Please select a valid workflow.", validationErr)
	}
	state.messages = append(state.messages, llm.Message{Role: "assistant", Content: state.content})
	state.messages = append(state.messages, llm.Message{Role: "user", Content: correctionMsg})

	corrLoopRes, corrErr := inv.runLLMLoop(ctx, state.messages, katypes.PhaseWorkflowDiscovery, llmCtx)
	if corrErr != nil {
		return nil, corrErr
	}
	// #1945 (main port #1936): the nested loop's accumulated tool-call
	// history must flow back into state.messages before the next
	// self-correction attempt's request is built from it — otherwise
	// attempt N+1 is missing every tool call made during attempt N's own
	// nested loop (list_workflows, etc.), independent of the top-level
	// reassignment in runWorkflowSelection above.
	if extended := loopResultMessages(corrLoopRes); len(extended) > 0 {
		state.messages = extended
	}
	return inv.classifySelfCorrectionLoopResult(corrLoopRes, r, state, rcaSummary)
}

type WorkflowDiscoveryResult struct {
	// Recommended is the top-ranked workflow.
	Recommended *DiscoveredWorkflow `json:"recommended,omitempty"`
	// Alternatives are additional workflows the user may choose from.
	Alternatives []DiscoveredWorkflow `json:"alternatives,omitempty"`
	// SearchedTarget is the resource that was searched against the workflow
	// catalog. Sourced from workflowResult.RemediationTarget (#1437).
	SearchedTarget *DiscoveryTargetInfo `json:"searched_target,omitempty"`
	// SignalTarget is the original alert resource before any RCA override.
	SignalTarget *DiscoveryTargetInfo `json:"signal_target,omitempty"`
	// FullResult is the complete InvestigationResult from Phase 3 (includes RCA +
	// workflow selection). Used to build the final result for the HTTP session.
	FullResult *katypes.InvestigationResult `json:"-"`
}

// isWorkflowInDiscoveryResult checks if the given workflow_id is in the
// discovery result (recommended or alternatives).
func isWorkflowInDiscoveryResult(workflowID string, dr *mcpinternal.WorkflowDiscoveryResult) bool {
	if dr.Recommended != nil && dr.Recommended.WorkflowID == workflowID {
		return true
	}
	for _, alt := range dr.Alternatives {
		if alt.WorkflowID == workflowID {
			return true
		}
	}
	return false
}

// buildFinalResult constructs the final InvestigationResult by merging the RCA
// with the selected workflow details from the catalog and per-workflow parameters
// from the discovery result (#1169).
func buildFinalResult(rca *katypes.InvestigationResult, workflow *CatalogWorkflow, discovery *mcpinternal.WorkflowDiscoveryResult) *katypes.InvestigationResult {
	result := *rca

	applyDiscoveryFullResult(&result, discovery)

	// KA-HIGH-1: Use Phase 3 confidence when a discovery recommendation exists,
	// since Phase 3 has additional workflow-specific scoring context.
	if discovery != nil && discovery.Recommended != nil && discovery.Recommended.Confidence > 0 {
		result.Confidence = discovery.Recommended.Confidence
	}

	applySelectedWorkflow(&result, workflow)

	if discovery != nil && workflow != nil {
		if params, found := lookupDiscoveredParameters(workflow.WorkflowID, discovery); found {
			result.Parameters = cloneParameterMap(params)
		}
	}

	// KA-MED-2: Propagate alternative workflows from discovery so AA and the
	// operator have visibility into what other options were available.
	result.AlternativeWorkflows = discoveryAlternativeWorkflows(discovery)

	// Re-inject KA-managed target resource parameters after the discovery
	// merge, which may have replaced the RCA parameter map entirely.
	investigator.InjectTargetResourceParameters(&result)

	return &result
}

func applySelectedWorkflow(result *katypes.InvestigationResult, workflow *CatalogWorkflow) {
	if workflow == nil {
		return
	}
	result.WorkflowID = workflow.WorkflowID
	result.ExecutionEngine = workflow.ExecutionEngine
	result.ExecutionBundle = workflow.ExecutionBundle
	result.ExecutionBundleDigest = workflow.ExecutionBundleDigest
	result.ServiceAccountName = workflow.ServiceAccountName
	result.ExecutionClusterID = workflow.ExecutionClusterID
	result.EngineConfig = workflow.EngineConfig
	result.Dependencies = workflow.Dependencies
	result.Resources = workflow.Resources
	result.DeclaredParameterNames = workflow.DeclaredParameterNames
	result.WorkflowVersion = workflow.Version
	result.WorkflowRationale = "User-selected via interactive mode"
	// Issue #1661 Change 12: catalog-authoritative, mirroring the
	// autonomous path's enrichFromCatalog -- CatalogWorkflow already
	// carries both from the DS catalog lookup one call up.
	result.ActionType = workflow.ActionType
	result.WorkflowName = workflow.WorkflowName
}

// discoveryAlternativeWorkflows converts the discovery result's alternative
// workflows into the katypes wire format, returning nil when there are none
// (preserving the original nil-vs-empty-slice semantics for callers that
// serialize this field).
func discoveryAlternativeWorkflows(discovery *mcpinternal.WorkflowDiscoveryResult) []katypes.AlternativeWorkflow {
	if discovery == nil || len(discovery.Alternatives) == 0 {
		return nil
	}
	alts := make([]katypes.AlternativeWorkflow, 0, len(discovery.Alternatives))
	for _, alt := range discovery.Alternatives {
		alts = append(alts, katypes.AlternativeWorkflow{
			WorkflowID:      alt.WorkflowID,
			ExecutionBundle: alt.ExecutionBundle,
			Confidence:      alt.Confidence,
			Rationale:       alt.Rationale,
			Parameters:      cloneParameterMap(alt.Parameters),
		})
	}
	return alts
}

// lookupDiscoveredParameters finds the parameter map for a given workflow_id
// in the discovery result (recommended or alternatives).

func WithWorkflowResultSchema() json.RawMessage {
	return json.RawMessage(investigationResultSchemaJSON)
}

func (v *Validator) GetWorkflowMeta(workflowID string) (WorkflowMeta, bool) {
	m, ok := v.catalogMeta[workflowID]
	return m, ok
}

// IsAllowed reports whether workflowID is present in the catalog allowlist and,
// when discovery state is attached, was returned by list_workflows in the
// current selection context. This
// is the same membership test Validate applies to workflow_id, exposed here
// so callers outside Validate (e.g. enrichFromCatalog's Issue #1711 guard)
// can distinguish "unresolvable ID" from "resolvable ID with no registered
// WorkflowMeta" -- the latter occurs only in test fixtures that populate the
// allowlist without a matching SetWorkflowMeta call; production always sets
// both from the same catalog-fetch loop (see dsCatalogFetcher.FetchValidator).
func (v *Validator) IsAllowed(workflowID string) bool {
	if _, ok := v.allowedWorkflows[workflowID]; !ok {
		return false
	}
	return v.discoveredWorkflows == nil || v.discoveredWorkflows.Contains(workflowID)
}

func (v *Validator) Validate(result *katypes.InvestigationResult) error {
	if result.HumanReviewNeeded {
		return nil
	}

	if result.WorkflowID != "" {
		if !v.IsAllowed(result.WorkflowID) {
			message := fmt.Sprintf("workflow %q not in session allowlist", result.WorkflowID)
			if _, catalogAllowed := v.allowedWorkflows[result.WorkflowID]; catalogAllowed && v.discoveredWorkflows != nil {
				message = fmt.Sprintf("workflow %q not returned by workflow discovery in current session", result.WorkflowID)
			}
			return &ValidationError{
				Field:   "workflow_id",
				Message: message,
			}
		}
	}

	if result.Confidence < 0 || result.Confidence > 1 {
		return &ValidationError{
			Field:   "confidence",
			Message: fmt.Sprintf("confidence %.2f out of [0, 1] range", result.Confidence),
		}
	}

	if result.WorkflowID != "" && result.Parameters != nil {
		if meta, ok := v.catalogMeta[result.WorkflowID]; ok {
			pvr := v.validateParameters(result.Parameters, meta.Parameters, meta.CompiledPatterns)
			if !pvr.IsValid {
				return &ParameterValidationError{Result: pvr}
			}
		}
	}

	return nil
}

