func (t *listActionsTool) Execute(ctx context.Context, args json.RawMessage) (string, error) {
	signal, err := signalFromContext(ctx, "listing action types")
	if err != nil {
		return "", err
	}

	var a struct {
		Page   string `json:"page"`
		Cursor string `json:"cursor"`
	}
	if err := json.Unmarshal(args, &a); err != nil {
		return "", fmt.Errorf("parsing args: %w", err)
	}

	filters := filtersFromSignal(signal)
	logr.FromContextOrDiscard(ctx).V(1).Info("list_available_actions: resolved component",
		"component", filters.Component, "remediation_id", signal.RemediationID)

	offset, limit := 0, defaultPaginationLimit
	if a.Page != "" && a.Cursor != "" {
		offset, limit = decodeCursor(a.Cursor)
	}

	if t.catalog == nil {
		return "", fmt.Errorf("listing action types: workflow catalog unavailable")
	}

	start := time.Now()
	entries, totalCount, err := t.catalog.ListActions(ctx, filters, offset, limit)
	durationMs := time.Since(start).Milliseconds()
	if err != nil {
		return "", fmt.Errorf("listing action types: %w", err)
	}

	t.emitAuditEvent(ctx, filters, totalCount, durationMs)

	resp := models.ActionTypeListResponse{
		ActionTypes: entries,
		Pagination: models.PaginationMetadata{
			TotalCount: totalCount,
			Offset:     offset,
			Limit:      limit,
			HasMore:    offset+limit < totalCount,
		},
	}
	data, err := json.Marshal(resp)
	if err != nil {
		return "", fmt.Errorf("marshaling action types response: %w", err)
	}
	return string(transformPagination(data)), nil
}

func matchesDetectedLabelsFilter(workflowDetected models.DetectedLabels, filterDetected *models.DetectedLabels) bool {
	if filterDetected == nil {
		return true
	}
	return matchesDetectedStringField(workflowDetected.GitOpsTool, filterDetected.GitOpsTool) &&
		matchesDetectedStringField(workflowDetected.ServiceMesh, filterDetected.ServiceMesh) &&
		matchesDetectedStringField(workflowDetected.StorageBackend, filterDetected.StorageBackend)
}

func matchesSearchFilters(rw *rwv1alpha1.RemediationWorkflow, filters *models.WorkflowSearchFilters) bool {
	if filters == nil {
		return true
	}
	if filters.WorkflowName != "" && rw.Name != filters.WorkflowName {
		return false
	}
	labels := crdLabelsToMandatoryLabels(rw.Spec.Labels)
	if !matchesArrayLabel(labels.Severity, filters.Severity) ||
		!matchesArrayLabel(labels.Component, filters.Component) ||
		!matchesArrayLabel(labels.Environment, filters.Environment) ||
		!matchesPriority(labels.Priority, filters.Priority) {
		return false
	}
	if len(filters.Status) > 0 && !containsValue(filters.Status, string(rw.Status.CatalogStatus)) {
		return false
	}
	return true
}

