// ========================================
// DETECTED LABELS (DD-WORKFLOW-001 v2.2)
// ========================================

// DetectedLabels contains auto-detected cluster characteristics.
// SignalProcessing populates these automatically from K8s resources.
// Used by KA for:
//   - Workflow filtering (deterministic SQL WHERE)
//   - LLM context (natural language in prompt)
//
// DETECTION FAILURE HANDLING (DD-WORKFLOW-001 v2.2):
// All fields are plain `bool` (NOT `*bool`). Uses `FailedDetections` array to track
// which fields had query failures (RBAC denied, timeout, network error).
//
// IMPORTANT DISTINCTION:
//   - Resource doesn't exist (no PDB) → false value, NOT in FailedDetections
//   - Query failed (RBAC denied) → false value, field name IN FailedDetections
//
// Consumers should check FailedDetections before trusting a false value.

// from the RO's remediation.workflow_created audit event.
// Returns empty string if DS is unavailable or no pre-hash exists (graceful degradation).
func (r *Reconciler) queryPreRemediationHash(ctx context.Context, correlationID string) string {
	if r.DSQuerier == nil {
		log.FromContext(ctx).V(1).Info("DSQuerier not configured, skipping pre-remediation hash lookup")
		return ""
	}

	preHash, err := r.DSQuerier.QueryPreRemediationHash(ctx, correlationID)
	if err != nil {
		log.FromContext(ctx).Error(err, "Failed to query pre-remediation hash from DataStorage",
			"correlationID", correlationID)
		r.Metrics.RecordExternalCallError("datastorage", "query_pre_hash", "query_error")
		return ""
	}

	if preHash != "" {
		log.FromContext(ctx).V(1).Info("Pre-remediation hash retrieved from DataStorage",
			"correlationID", correlationID,
			"preHash", preHash[:min(23, len(preHash))]+"...")
	}
	return preHash
}

