func (h *ExecutingHandler) setWorkflowConditions(ctx context.Context, rr *remediationv1.RemediationRequest, we *workflowexecutionv1.WorkflowExecution) {
	logger := log.FromContext(ctx).WithValues("remediationRequest", rr.Name)

	switch we.Status.Phase {
	case workflowexecutionv1.PhaseCompleted:
		if err := h.statusManager.AtomicStatusUpdate(ctx, rr, func() error {
			remediationrequest.SetWorkflowExecutionComplete(rr, true,
				remediationrequest.ReasonWorkflowSucceeded,
				"WorkflowExecution completed successfully", h.metrics)
			return nil
		}); err != nil {
			logger.Error(err, "Failed to update WorkflowExecutionComplete condition")
		}
	case workflowexecutionv1.PhaseFailed:
		if err := h.statusManager.AtomicStatusUpdate(ctx, rr, func() error {
			remediationrequest.SetWorkflowExecutionComplete(rr, false,
				remediationrequest.ReasonWorkflowFailed,
				"WorkflowExecution failed", h.metrics)
			return nil
		}); err != nil {
			logger.Error(err, "Failed to update WorkflowExecutionComplete condition")
		}
	}
}

func buildWorkflowDiscoveryPayload(event *AuditEvent, eventType ogenclient.WorkflowDiscoveryAuditPayloadEventType) ogenclient.WorkflowDiscoveryAuditPayload {
	totalCount := dataInt(event.Data, "total_count")

	var searchFilters ogenclient.OptWorkflowSearchFilters
	if hasDiscoveryFilters(event.Data) {
		wsf := ogenclient.WorkflowSearchFilters{
			Severity:    ogenclient.WorkflowSearchFiltersSeverity(dataString(event.Data, "severity")),
			Component:   dataString(event.Data, "component"),
			Environment: dataString(event.Data, "environment"),
			Priority:    ogenclient.WorkflowSearchFiltersPriority(dataString(event.Data, "priority")),
		}
		if labels, ok := detectedLabelsFromJSON(event.Data); ok {
			wsf.DetectedLabels.SetTo(labels)
		}
		searchFilters.SetTo(wsf)
	}

	return ogenclient.WorkflowDiscoveryAuditPayload{
		EventType: eventType,
		Query: ogenclient.QueryMetadata{
			TopK:    int32(totalCount),
			Filters: searchFilters,
		},
		Results: ogenclient.ResultsMetadata{
			TotalFound: int32(totalCount),
			Returned:   int32(totalCount),
		},
		SearchMetadata: ogenclient.SearchExecutionMetadata{
			DurationMs: int64(dataInt(event.Data, "duration_ms")),
		},
	}
}

func (inv *Investigator) runWorkflowDiscoveryPhase(ctx context.Context, p workflowDiscoveryPhaseParams) (*katypes.InvestigationResult, error) {
	// GAP-001 / ADR-056: Re-enrich using RCA-identified remediation target if
	// different. H3-fix: retain pre-RCA enrichment if re-enrichment fails.
	workflowSignal, enrichData, hardFailed := inv.reEnrichWorkflowTarget(ctx, reEnrichWorkflowTargetParams{
		Signal: p.Signal, RCAResult: p.RCAResult, EnrichData: p.EnrichData, EnrichmentCache: p.EnrichmentCache,
		SignalKind: p.SignalKind, SignalName: p.SignalName, SignalNS: p.SignalNS,
	})
	if hardFailed {
		return inv.finalizeAndEmitRCAOnlyResult(ctx, p.RCAResult, p.Signal, enrichData, p.Tokens, p.CorrelationID), nil
	}
	promptEnrichment := toPromptEnrichment(enrichData)
	workflowSignal = inv.enrichWorkflowSignalForDiscovery(workflowSignal, p.Signal, p.RCAResult, enrichData, p.CorrelationID)

	inv.anomalyDetectorFor(p.CorrelationID).Reset()

	wfClient, wfModelName, wfRuntimeParams := inv.resolveForPhase(katypes.PhaseWorkflowDiscovery)

	p1Ctx := BuildPhase1Context(p.RCAResult)

	workflowResult, err := inv.runWorkflowSelection(ctx, workflowSignal, p.RCAResult.RCASummary, promptEnrichment, p1Ctx, LLMInvocationContext{
		Tokens:        p.Tokens,
		CorrelationID: p.CorrelationID,
		Client:        wfClient,
		ModelName:     wfModelName,
		RuntimeParams: wfRuntimeParams,
	})
	if err != nil {
		return nil, fmt.Errorf("workflow selection invocation: %w", err)
	}

	if workflowResult.Cancelled {
		// #2387: see the RCA-cancelled path above — partial counts apply here too.
		inv.applyMetricsFromScope(workflowResult, p.CorrelationID)
		inv.setTokenUsageFromScope(workflowResult, p.CorrelationID)
		inv.emitCancellationAudit(ctx, workflowResult, p.CorrelationID)
		return workflowResult, nil
	}

	return inv.mergeAndFinalizeWorkflowResult(ctx, mergeAndFinalizeWorkflowResultParams{
		WorkflowResult: workflowResult, RCAResult: p.RCAResult, Signal: p.Signal, WorkflowSignal: workflowSignal,
		EnrichData: enrichData, P1Ctx: p1Ctx, Tokens: p.Tokens, CorrelationID: p.CorrelationID,
	}), nil
}

func (inv *Investigator) retryForAPIVersion(ctx context.Context, p retryForAPIVersionParams) *katypes.InvestigationResult {
	result, history := p.Result, p.History
	kind, groupList, correlationID, gateEvent := p.Kind, p.GroupList, p.CorrelationID, p.GateEvent
	llmCtx := LLMInvocationContext{
		Tokens: p.Tokens, CorrelationID: p.CorrelationID, Client: p.Client,
		RuntimeParams: p.RuntimeParams,
	}
	correctionMsg := fmt.Sprintf(
		`Your remediation_target.kind is %q, which exists in multiple API groups: %s. `+
			`Without an explicit api_version, the system cannot determine the correct API group `+
			`and may grant RBAC permissions to the wrong resource. `+
			`You MUST re-submit your result with the api_version field set to the correct `+
			`"group/version" (e.g. "operators.coreos.com/v1alpha1"). `+
			`Review your investigation context (kubectl_describe output) to determine which `+
			`API group the target %s/%s belongs to.`,
		kind, groupList, kind, result.RemediationTarget.Name,
	)
	retryMessages := appendCorrectionMessage(history, correctionMsg)
	submitOnlyTools := submitOnlyRCATools()

	// #1777 (BR-AUDIT-005, FedRAMP AU-3): the audit event must reflect the
	// retry prompt actually sent to the LLM. Populating these fields before
	// retryMessages exists forced prompt_length/prompt_preview to a
	// hardcoded 0/"" that misrepresented every gate retry as an empty
	// request.
	gateEvent.Data["prompt_length"] = totalPromptLength(retryMessages)
	gateEvent.Data["prompt_preview"] = lastUserMessage(retryMessages)
	// #2121 (BR-AI-2121, FedRAMP AU-3): fire once, after the final outcome is
	// known, via defer -- this also fixes a pre-existing bug (#2124) where
	// gateEvent.Data["retry_outcome"] was mutated below AFTER this store
	// call fired, so a production audit store (which serializes Data into
	// an outbound request synchronously at call time) never actually
	// persisted retry_outcome.
	defer audit.StoreBestEffort(ctx, inv.auditStore, gateEvent, inv.auditLog())

	// #2088 (main port of #2086): same silent-gap risk as retryForSameKind
	// above -- this retry LLM call is non-streamed and emits no sink events
	// during the round-trip.
	emitGateRetryKeepalive(ctx, "resolving_api_version_ambiguity")

	resp, retryErr := llm.ChatWithParams(ctx, llmCtx.Client, llm.ChatRequest{
		Messages: retryMessages,
		Tools:    submitOnlyTools,
		Options:  llm.ChatOptions{JSONMode: true, OutputSchema: parser.RCAResultSchema()},
	}, llmCtx.RuntimeParams)
	if retryErr != nil {
		inv.logger.Error(retryErr, "apiVersionValidationGate: retry failed, triggering human review",
			"kind", kind, "correlation_id", correlationID)
		return inv.apiVersionGateExhaustion(result, groupList, kind, correlationID, gateEvent, gateRetryExhausted)
	}
	if llmCtx.Tokens != nil {
		llmCtx.Tokens.Add(resp.Usage)
	}
	// #2387: gate retry is its own LLM turn on top of the loop-counted turns.
	inv.metricsFor(correlationID).IncLLMTurns()
	inv.recordTokenUsage(correlationID, resp.Usage)

	retryContent, usedReminder, failOutcome, ok := inv.resolveGateRetrySubmission(
		ctx, llmCtx, retryMessages, resp, submitOnlyTools, gateEvent, "apiVersionValidationGate")
	if !ok {
		inv.logger.Info("apiVersionValidationGate: triggering human review after unresolved retry",
			"kind", kind, "retry_outcome", failOutcome, "correlation_id", correlationID)
		return inv.apiVersionGateExhaustion(result, groupList, kind, correlationID, gateEvent, failOutcome)
	}

	retryResult, parseErr := inv.resultParser.Parse(retryContent)
	if parseErr != nil {
		inv.logger.Error(parseErr, "apiVersionValidationGate: retry parse failed, triggering human review",
			"correlation_id", correlationID)
		return inv.apiVersionGateExhaustion(result, groupList, kind, correlationID, gateEvent, gateRetryParseError)
	}

	if retryResult.RemediationTarget.APIVersion == "" {
		inv.logger.Info("apiVersionValidationGate: retry still missing api_version, triggering human review",
			"kind", kind, "correlation_id", correlationID)
		return inv.apiVersionGateExhaustion(result, groupList, kind, correlationID, gateEvent, gateRetryExhausted)
	}

	gateEvent.EventOutcome = audit.OutcomeSuccess
	if usedReminder {
		gateEvent.Data["retry_outcome"] = string(gateRetryResolvedAfterReminder)
	} else {
		gateEvent.Data["retry_outcome"] = string(gateRetryResolved)
	}
	// Clear parser-set HumanReviewNeeded from the retry result. The gate's
	// decision is authoritative: if the retry provided api_version, the
	// pipeline should continue to workflow selection, not abort.
	retryResult.HumanReviewNeeded = false
	retryResult.HumanReviewReason = ""
	// The retry is a fresh submission on its own turn: its own Reasoning
	// block (if any) is authoritative for the accepted result, mirroring
	// runRCA's "winning turn" semantics (BR-AI-086 AC6, #1578). Without this,
	// resp.Message.Reasoning from the retry call is silently discarded and
	// the gate-accepted result loses reasoning captured by the LLM client.
	retryResult.Reasoning = toReasoningSummary(resp.Message.Reasoning)
	inv.logger.Info("apiVersionValidationGate: retry provided api_version, accepted",
		"kind", kind,
		"api_version", retryResult.RemediationTarget.APIVersion,
		"correlation_id", correlationID)
	return retryResult
}

func (inv *Investigator) runWorkflowSelection(ctx context.Context, signal katypes.SignalContext, rcaSummary string, enrichData *prompt.EnrichmentData, p1Ctx *prompt.Phase1Data, llmCtx LLMInvocationContext) (result *katypes.InvestigationResult, retErr error) {
	correlationID := llmCtx.CorrelationID
	// Apply signal label overrides (target_resource_kind / target_resource_name)
	// before attaching to context. This ensures workflow discovery tools
	// (list_available_actions, list_workflows) filter by the correct component.
	// Defense-in-depth for #1064/#1065: even if enrichment resolved a container
	// kind (e.g. Namespace), the label override corrects it for tool context.
	discoveredWorkflows := katypes.NewDiscoveredWorkflowState()
	ctx = katypes.WithDiscoveredWorkflowState(ctx, discoveredWorkflows)
	overriddenSignal := ApplySignalLabelOverrides(signal)
	ctx = katypes.WithSignalContext(ctx, overriddenSignal)
	inv.logger.Info("runWorkflowSelection: post-override signal",
		"component_gvk", overriddenSignal.ComponentGVK(),
		"resource_kind", overriddenSignal.ResourceKind,
		"resource_api_version", overriddenSignal.ResourceAPIVersion,
		"correlation_id", correlationID)

	wfPromptSignal := SignalToPrompt(signal)
	LogLabelOverrideOrRejection(inv.logger, signal, wfPromptSignal, correlationID, "workflow selection")
	systemPrompt, err := inv.builder.RenderWorkflowSelection(prompt.WorkflowSelectionInput{
		Signal:                          wfPromptSignal,
		RCASummary:                      rcaSummary,
		EnrichData:                      enrichData,
		Phase1:                          p1Ctx,
		ResolvedConfidenceThreshold:     inv.resolvedConfidenceThreshold,
		InconclusiveConfidenceThreshold: inv.inconclusiveConfidenceThreshold,
	})
	if err != nil {
		return nil, fmt.Errorf("rendering workflow selection prompt: %w", err)
	}
	llmCtx.WorkflowDiscovery = newWorkflowDiscoveryAuditContext(enrichData, overriddenSignal, systemPrompt)

	messages := []llm.Message{
		{Role: "system", Content: systemPrompt},
		{Role: "user", Content: fmt.Sprintf("RCA findings: %s\n\nSelect the appropriate remediation workflow.", rcaSummary)},
	}

	loopRes, err := inv.runLLMLoop(ctx, messages, katypes.PhaseWorkflowDiscovery, llmCtx)
	if err != nil {
		return nil, err
	}
	// #1935/#1936 root cause #2 (workflow-discovery extension, #1945):
	// runLLMLoop's accumulated tool-call history must flow back into
	// messages before it feeds handleWorkflowSelectionLoopResult (and, via
	// it, retryWorkflowSubmit's two call sites and selfCorrectWorkflowSelection
	// below) — otherwise every retry/self-correction attempt operates on a
	// stale [system, user]-only slice regardless of how many
	// list_available_actions/list_workflows calls actually ran.
	if extended := loopResultMessages(loopRes); len(extended) > 0 {
		messages = extended
	}

	content, early := inv.handleWorkflowSelectionLoopResult(ctx, loopRes, rcaSummary, messages, llmCtx)
	if early != nil {
		return early, nil
	}

	result, parseErr := inv.resultParser.Parse(content)
	if parseErr != nil {
		var terminal *katypes.InvestigationResult
		content, terminal = inv.workflowSelectionRetryOrHumanReview(ctx, content, messages, rcaSummary, llmCtx, parseErr,
			fmt.Sprintf("workflow selection: LLM did not produce parseable result: %s", parseErr))
		if terminal != nil {
			return terminal, nil
		}
		// Genuine workflow selection recovered via retryWorkflowSubmit: fall
		// through into the same CatalogFetcher / selfCorrectWorkflowSelection
		// validation path below, exactly like a first-attempt success.
		// Returning it directly here would bypass catalog validation for
		// this specific retry path (#1677 follow-up hardening).
		result, parseErr = inv.resultParser.Parse(content)
		if parseErr != nil {
			return nil, fmt.Errorf("workflow selection: re-parsing retry-recovered content: %w", parseErr)
		}
	}

	// #1677 hardening (DD-WORKFLOW-019): CatalogFetcher is always configured
	// in production (cmd/kubernautagent always wires a workflowCatalogFetcher
	// backed by a LazyCatalog, ready or not) -- a nil CatalogFetcher here is
	// a test/wiring gap, not a supported "dev mode" that should silently
	// bypass validation. result.HumanReviewNeeded already true means the
	// parser/LLM itself determined no workflow selection needs validating
	// (e.g. no_matching_workflows) -- that classification is preserved
	// as-is, matching selfCorrectWorkflowSelection's own contract of only
	// running validation when there is an actual selection to validate.
	// Otherwise (a workflow WAS selected) failing closed instead of
	// returning it unvalidated mirrors selfCorrectWorkflowSelection's own
	// fetchErr handling below, so both "no fetcher configured" and "fetcher
	// configured but catalog not ready/unreachable" produce the same
	// observable outcome: human review, never silent pass-through.
	if inv.pipeline.CatalogFetcher == nil {
		if result.HumanReviewNeeded {
			return result, nil
		}
		inv.logger.Error(nil, "workflow catalog fetcher not configured, requiring human review instead of skipping validation",
			"correlation_id", correlationID)
		result.HumanReviewNeeded = true
		result.HumanReviewReason = "catalog_unavailable"
		result.Reason = "workflow catalog fetcher not configured"
		return result, nil
	}
	return inv.selfCorrectWorkflowSelection(ctx, result, content, messages, rcaSummary, correlationID, llmCtx)
}

func (inv *Investigator) selfCorrectWorkflowSelection(ctx context.Context, result *katypes.InvestigationResult, content string, messages []llm.Message, rcaSummary, correlationID string, llmCtx LLMInvocationContext) (*katypes.InvestigationResult, error) {
	validator, fetchErr := inv.pipeline.CatalogFetcher.FetchValidator(ctx)
	if fetchErr != nil {
		inv.logger.Error(fetchErr, "workflow catalog unavailable, requiring human review")
		result.HumanReviewNeeded = true
		result.HumanReviewReason = "catalog_unavailable"
		result.Reason = fmt.Sprintf("workflow catalog unavailable: %s", fetchErr)
		return result, nil
	}
	if discoveredWorkflows, ok := katypes.DiscoveredWorkflowStateFromContext(ctx); ok {
		validator.SetDiscoveredWorkflowState(discoveredWorkflows)
	}

	state := &selfCorrectionState{content: content, messages: messages}
	correctionFn := func(r *katypes.InvestigationResult, validationErr error) (*katypes.InvestigationResult, error) {
		return inv.runSelfCorrectionAttempt(ctx, r, validationErr, state, rcaSummary, correlationID, llmCtx)
	}

	corrected, corrErr := validator.SelfCorrect(result, maxSelfCorrectionAttempts, correctionFn)
	if corrErr != nil {
		return handleSelfCorrectError(corrErr, rcaSummary)
	}
	return inv.finalizeSelfCorrection(ctx, corrected, state.attempt, correlationID, validator), nil
}

func (inv *Investigator) runSelfCorrectionAttempt(ctx context.Context, r *katypes.InvestigationResult, validationErr error, state *selfCorrectionState, rcaSummary, correlationID string, llmCtx LLMInvocationContext) (*katypes.InvestigationResult, error) {
	state.attempt++
	var errStrs []string
	if validationErr != nil {
		errStrs = []string{validationErr.Error()}
	}
	inv.emitValidationEvent(ctx, state.attempt, maxSelfCorrectionAttempts, false, errStrs, r.WorkflowID, correlationID)

	correctionMsg, renderErr := inv.renderCorrectionMessage(validationErr, state.attempt, maxSelfCorrectionAttempts)
	if renderErr != nil {
		inv.logger.Error(renderErr, "failed to render validation error template, using fallback")
		correctionMsg = fmt.Sprintf("Validation failed: %s. Please select a valid workflow.", validationErr)
	}
	state.messages = append(state.messages, llm.Message{Role: "assistant", Content: state.content})
	state.messages = append(state.messages, llm.Message{Role: "user", Content: correctionMsg})

	corrLoopRes, corrErr := inv.runLLMLoop(ctx, state.messages, katypes.PhaseWorkflowDiscovery, llmCtx)
	if corrErr != nil {
		return nil, corrErr
	}
	// #1945 (main port #1936): the nested loop's accumulated tool-call
	// history must flow back into state.messages before the next
	// self-correction attempt's request is built from it — otherwise
	// attempt N+1 is missing every tool call made during attempt N's own
	// nested loop (list_workflows, etc.), independent of the top-level
	// reassignment in runWorkflowSelection above.
	if extended := loopResultMessages(corrLoopRes); len(extended) > 0 {
		state.messages = extended
	}
	return inv.classifySelfCorrectionLoopResult(corrLoopRes, r, state, rcaSummary)
}

func (t *InvestigateTool) persistPendingDecision(rrID string, workflowResult *katypes.InvestigationResult) {
	if workflowResult == nil || (workflowResult.HumanReviewNeeded && workflowResult.HumanReviewReason == "no_matching_workflows") {
		return
	}
	if t.httpCompleter == nil {
		return
	}
	httpSessionID, found := t.httpCompleter.FindUserDrivingByRemediationID(rrID)
	if !found {
		return
	}
	preview := *workflowResult
	preview.HumanReviewNeeded = true
	preview.HumanReviewReason = katypes.HumanReviewReasonDecisionExpired
	t.httpCompleter.PersistPendingDecisionResult(httpSessionID, &preview)
}

func (v *Validator) SetDiscoveredWorkflowState(state *katypes.DiscoveredWorkflowState) {
	v.discoveredWorkflows = state
}

func (v *Validator) SelfCorrect(result *katypes.InvestigationResult, maxAttempts int,
	correctionFn func(result *katypes.InvestigationResult, err error) (*katypes.InvestigationResult, error),
) (*katypes.InvestigationResult, error) {
	current := result
	var history []katypes.ValidationAttemptRecord
	var lastErr error

	for attempt := 0; attempt < maxAttempts; attempt++ {
		validationErr := v.Validate(current)
		if validationErr == nil {
			history = append(history, katypes.ValidationAttemptRecord{
				Attempt:    attempt + 1,
				WorkflowID: current.WorkflowID,
				IsValid:    true,
				Timestamp:  time.Now().UTC().Format(time.RFC3339),
			})
			current.ValidationAttemptsHistory = history
			return current, nil
		}

		lastErr = validationErr

		var errStrings []string
		var paramErr *ParameterValidationError
		if errors.As(validationErr, &paramErr) {
			errStrings = paramErr.Result.Errors
		} else {
			errStrings = []string{validationErr.Error()}
		}

		history = append(history, katypes.ValidationAttemptRecord{
			Attempt:    attempt + 1,
			WorkflowID: current.WorkflowID,
			IsValid:    false,
			Errors:     errStrings,
			Timestamp:  time.Now().UTC().Format(time.RFC3339),
		})

		if attempt < maxAttempts-1 {
			corrected, corrErr := correctionFn(current, validationErr)
			if corrErr != nil {
				return nil, fmt.Errorf("correction function failed on attempt %d: %w", attempt+1, corrErr)
			}
			current = corrected
		}
	}

	current.ValidationAttemptsHistory = history
	current.HumanReviewNeeded = true
	current.HumanReviewReason = "llm_parsing_error"
	current.Reason = fmt.Sprintf("self-correction exhausted after %d attempts: %s", maxAttempts, lastErr)
	current.WorkflowID = ""
	current.ExecutionBundle = ""
	return current, nil
}

