// CompleteUserDriving transitions a user-driven session to completed with the
// given result. This bridges the MCP tool completion path to the HTTP session
// store so AA's poll mechanism picks up the result.

func (t *listActionsTool) Execute(ctx context.Context, args json.RawMessage) (string, error) {
	signal, err := signalFromContext(ctx, "listing action types")
	if err != nil {
		return "", err
	}

	var a struct {
		Page   string `json:"page"`
		Cursor string `json:"cursor"`
	}
	if err := json.Unmarshal(args, &a); err != nil {
		return "", fmt.Errorf("parsing args: %w", err)
	}

	filters := filtersFromSignal(signal)
	logr.FromContextOrDiscard(ctx).V(1).Info("list_available_actions: resolved component",
		"component", filters.Component, "remediation_id", signal.RemediationID)

	offset, limit := 0, defaultPaginationLimit
	if a.Page != "" && a.Cursor != "" {
		offset, limit = decodeCursor(a.Cursor)
	}

	if t.catalog == nil {
		return "", fmt.Errorf("listing action types: workflow catalog unavailable")
	}

	start := time.Now()
	entries, totalCount, err := t.catalog.ListActions(ctx, filters, offset, limit)
	durationMs := time.Since(start).Milliseconds()
	if err != nil {
		return "", fmt.Errorf("listing action types: %w", err)
	}

	t.emitAuditEvent(ctx, filters, totalCount, durationMs)

	resp := models.ActionTypeListResponse{
		ActionTypes: entries,
		Pagination: models.PaginationMetadata{
			TotalCount: totalCount,
			Offset:     offset,
			Limit:      limit,
			HasMore:    offset+limit < totalCount,
		},
	}
	data, err := json.Marshal(resp)
	if err != nil {
		return "", fmt.Errorf("marshaling action types response: %w", err)
	}
	return string(transformPagination(data)), nil
}

func (c *Catalog) ListWorkflowsByActionType(ctx context.Context, actionType string, filters *models.WorkflowDiscoveryFilters, offset, limit int) ([]models.RemediationWorkflow, int, error) {
	return c.listWorkflowsByActionTypeFromCache(ctx, actionType, filters, offset, limit)
}

func recordDiscoverWorkflowsCheckpoint(ctx agent.Context, resp map[string]any) {
	state := ctx.State()
	if state == nil {
		return
	}
	logger := logr.FromContextOrDiscard(ctx)
	mode := interactionModeFromState(state)
	blocked := mode != session.InteractionModeFullRemediationAutonomous
	if err := state.Set(session.StateKeyPhase3Blocked, blocked); err != nil {
		logger.Error(err, "phase-guard failed to persist phase3_blocked state")
	}
	// #2098 (v1.6 clone #2099): unblocks presentDecisionRequiresDiscoveryFirst's
	// ordering guard for the remainder of this driver session.
	if err := state.Set(session.StateKeyDiscoverWorkflowsSucceeded, true); err != nil {
		logger.Error(err, "phase-guard failed to persist discover_workflows_succeeded state")
	}
	if err := state.Set(session.StateKeyDiscoveryResult, resp); err != nil {
		logger.Error(err, "phase-guard failed to persist discovery_result state")
	}
	obligation := session.DecisionObligation(mode, true, blocked)
	status := session.DecisionArtifactNotRequired
	if obligation.PresentationRequired {
		status = session.DecisionArtifactRequired
	}
	if err := state.Set(session.StateKeyDecisionArtifactStatus, status); err != nil {
		logger.Error(err, "phase-guard failed to persist decision_artifact_status state")
	}
	// The legacy generic-reinvocation recovery flag remains inert. #2365
	// presentation obligations are tracked independently above and enforced by
	// the business-outcome coordinator, so recovery cannot bypass phase-3
	// consent or autonomous workflow chaining.
	if err := state.Set(session.StateKeyPresentationRequired, false); err != nil {
		logger.Error(err, "phase-guard failed to persist presentation_required state")
	}
	if err := state.Set(session.StateKeyPresentationRecoveryCount, 0); err != nil {
		logger.Error(err, "phase-guard failed to reset presentation recovery count")
	}
}

func HandleDiscoverWorkflows(ctx context.Context, mcpClient ka.MCPClient, args DiscoverWorkflowsArgs) (DiscoverWorkflowsResult, error) {
	if args.RRID != "" {
		if err := validate.RRID(args.RRID); err != nil {
			return DiscoverWorkflowsResult{}, fmt.Errorf("invalid rr_id: %w", err)
		}
	}
	if mcpClient == nil {
		return DiscoverWorkflowsResult{}, fmt.Errorf("workflow discovery is not available: MCP client not configured")
	}

	toolCtx, cancel := context.WithTimeout(ctx, PooledToolCallTimeout)
	defer cancel()
	start := time.Now()
	kaResult, err := mcpClient.DiscoverWorkflows(toolCtx, ka.DiscoverWorkflowsArgs{
		RRID:       args.RRID,
		WorkflowID: args.WorkflowID,
		Kind:       args.Kind,
	})
	if err != nil {
		if errors.Is(err, context.DeadlineExceeded) || errors.Is(err, context.Canceled) {
			logPooledToolTimeoutFired(ctx, "discover_workflows", args.RRID, start)
			return DiscoverWorkflowsResult{Workflows: []WorkflowDetail{}, Count: 0}, nil
		}
		return DiscoverWorkflowsResult{}, fmt.Errorf("discover workflows: %w", err)
	}

	workflows := make([]WorkflowDetail, 0, len(kaResult.Workflows))
	for _, w := range kaResult.Workflows {
		params := make([]WorkflowParameter, 0, len(w.Parameters))
		for _, p := range w.Parameters {
			params = append(params, WorkflowParameter{
				Name:        p.Name,
				Type:        p.Type,
				Description: p.Description,
				Required:    p.Required,
				Default:     p.Default,
				Enum:        p.Enum,
			})
		}
		workflows = append(workflows, WorkflowDetail{
			WorkflowID:  w.WorkflowID,
			Name:        w.Name,
			Description: w.Description,
			Kind:        w.Kind,
			Confidence:  w.Confidence,
			Parameters:  params,
		})
	}

	result := DiscoverWorkflowsResult{
		Workflows: workflows,
		Count:     len(workflows),
	}
	if kaResult.SearchedTarget != nil {
		result.SearchedTarget = &TargetInfo{
			APIVersion: kaResult.SearchedTarget.APIVersion,
			Kind:       kaResult.SearchedTarget.Kind,
			Name:       kaResult.SearchedTarget.Name,
			Namespace:  kaResult.SearchedTarget.Namespace,
		}
	}
	if kaResult.SignalTarget != nil {
		result.SignalTarget = &TargetInfo{
			APIVersion: kaResult.SignalTarget.APIVersion,
			Kind:       kaResult.SignalTarget.Kind,
			Name:       kaResult.SignalTarget.Name,
			Namespace:  kaResult.SignalTarget.Namespace,
		}
	}
	return result, nil
}

