}

// Start performs the full startup reconciliation: list CRDs, sync with DS,

// is gated on. Without excluding it, the count would be permanently
// off-by-one-high after every deletion, with no later trigger to correct it.
// Callers with no such self-reference (e.g. the ActionType DELETE dependents
// gate) pass "".
//
// #1661 Change 8d: this is now the SOLE dependents check for ActionType
// deletion and the sole source for status.activeWorkflowCount. DS's Postgres
// catalog stopped learning about RemediationWorkflow CRDs the moment Change
// 8c removed AW's CreateWorkflowInline call, so any DS-backed dependents
// check is permanently blind to workflows created after that point -- the
// safety gap this change closes (IT-AW-1111-009). The live etcd list (via
// the cache-backed k8sClient) reflects every write once the informer's watch
// catches up, so there is no "orphan recovery" reconciliation to perform:

func (c *CRDCreator) createCRDWithRetry(ctx context.Context, rr *remediationv1alpha1.RemediationRequest, signal *types.NormalizedSignal) error {
	startTime := c.clock.Now()

	for attempt := 0; attempt < c.retryConfig.MaxAttempts; attempt++ {
		// Attempt CRD creation
		err := c.k8sClient.CreateRemediationRequest(ctx, rr)

		// Success path
		if err == nil {
			c.logSuccessAfterRetry(attempt, startTime, rr)
			return nil
		}

		// Handle special cases with dedicated error handlers
		if k8serrors.IsAlreadyExists(err) {
			return c.handleAlreadyExistsError(ctx, rr)
		}

		// Determine if error is retryable
		if !c.shouldRetryError(err) {
			errorType := getErrorTypeString(err)
			c.logger.Error(err, "CRD creation failed with non-retryable error",
				"name", rr.Name,
				"namespace", rr.Namespace,
				"error_type", errorType)
			return err
		}

		// BR-GATEWAY-058: Notify observer for each intermediate retry attempt.
		// The final attempt's audit event is emitted by the caller after this method returns.
		if attempt < c.retryConfig.MaxAttempts-1 {
			c.retryObserver.OnRetryAttempt(ctx, signal, attempt, err)
		}

		// Check if this was the last attempt
		if attempt == c.retryConfig.MaxAttempts-1 {
			return c.wrapRetryExhaustedError(err, attempt, startTime, rr)
		}

		// Wait with exponential backoff before next attempt
		if backoffErr := c.waitWithBackoff(ctx, attempt, err, rr); backoffErr != nil {
			return backoffErr // Context cancelled
		}
	}

	// Defensive: This should never be reached due to the last attempt check above
	// If we reach here, it indicates a logic error in the retry loop
	return fmt.Errorf("retry logic error: loop completed without explicit return (max_attempts=%d)", c.retryConfig.MaxAttempts)
}

func (s *DiscoveredWorkflowState) Add(workflowIDs ...string) {
	if s == nil {
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.workflowIDs == nil {
		s.workflowIDs = make(map[string]struct{})
	}
	for _, workflowID := range workflowIDs {
		if workflowID != "" {
			s.workflowIDs[workflowID] = struct{}{}
		}
	}
}

