func sortWorkflowsByCreatedAtDesc(workflows []models.RemediationWorkflow) {
	sort.SliceStable(workflows, func(i, j int) bool {
		if !workflows[i].CreatedAt.Equal(workflows[j].CreatedAt) {
			return workflows[i].CreatedAt.After(workflows[j].CreatedAt)
		}
		return workflows[i].WorkflowID < workflows[j].WorkflowID
	})
}

func registerKAMCPTools(srv *mcp.Server, cfg *MCPBridgeConfig, sem *semaphore.Weighted, shouldRegister toolGate) {
	if shouldRegister("kubernaut_select_workflow") {
		registerTool(srv, cfg, sem, "kubernaut_select_workflow", "Select a workflow for an investigation",
			func(ctx context.Context, args tools.SelectWorkflowArgs) (any, error) {
				return tools.HandleSelectWorkflow(ctx, cfg.KAMCPClient, args, cfg.Auditor)
			})
	}

	if shouldRegister("kubernaut_discover_workflows") {
		registerTool(srv, cfg, sem, "kubernaut_discover_workflows", "Discover available workflows with parameter schemas",
			func(ctx context.Context, args tools.DiscoverWorkflowsArgs) (any, error) {
				result, err := tools.HandleDiscoverWorkflows(ctx, cfg.KAMCPClient, args)
				if err != nil {
					return result, err
				}
				emitAudit(ctx, cfg, "kubernaut_discover_workflows", audit.EventWorkflowDiscovery,
					map[string]string{"rr_id": args.RRID, "workflow_count": strconv.Itoa(result.Count)},
					withCorrelationID(args.RRID))
				return result, nil
			})
	}

	if shouldRegister("kubernaut_present_decision") {
		registerTool(srv, cfg, sem, "kubernaut_present_decision", "Present a decision point requiring user input",
			func(_ context.Context, args tools.PresentDecisionArgs) (any, error) {
				return tools.HandlePresentDecision(args), nil
			})
	}

	// kubernaut_list_workflows: moved from registerDSTools -- now backed by
	// KA's workflow catalog (cache-backed), not DS's REST API. #1677 Phase
	// 2f (DD-WORKFLOW-019).
	//
	// Bug fix (found via E2E TC-E2E-MCP-FULL-03, CI run on #1718): this was
	// wired to cfg.KAMCPClient (PooledMCPClient), which always fails --
	// ListWorkflows is a stateless catalog browse with no rr_id to key a
	// pooled session on (see PooledMCPClient.ListWorkflows's own doc
	// comment), so every call returned "ListWorkflows is a stateless
	// catalog query; use SDKMCPClient for non-interactive calls" instead of
	// a workflow list. registerInvestigationTool already established the
	// correct pattern for this exact class of stateless call (prefer
	// KADedicatedClient, the SDKMCPClient, falling back to KAMCPClient) --
	// this mirrors it.
	registerTool(srv, cfg, sem, "kubernaut_list_workflows", "List available workflows",
		func(ctx context.Context, args tools.ListWorkflowsArgs) (any, error) {
			listClient := cfg.KADedicatedClient
			if listClient == nil {
				listClient = cfg.KAMCPClient
			}
			return tools.HandleListWorkflowsKA(ctx, listClient, args)
		})
}

func HandleListWorkflowsKA(ctx context.Context, mcpClient ka.MCPClient, args ListWorkflowsArgs) (ListWorkflowsResult, error) {
	if mcpClient == nil {
		return ListWorkflowsResult{}, fmt.Errorf("workflow catalog is not available: MCP client not configured")
	}

	kaResult, err := mcpClient.ListWorkflows(ctx, ka.ListWorkflowsArgs{Kind: args.Kind})
	if err != nil {
		return ListWorkflowsResult{}, fmt.Errorf("listing workflows: %w", err)
	}

	summaries := make([]WorkflowSummary, 0, len(kaResult.Workflows))
	for _, w := range kaResult.Workflows {
		summaries = append(summaries, WorkflowSummary{
			ID: w.ID, Name: w.Name, Description: w.Description, Kind: w.Kind,
		})
	}

	return ListWorkflowsResult{Workflows: summaries, Count: len(summaries)}, nil
}

// NewDiscoveredWorkflowState creates empty workflow-discovery state.
func NewDiscoveredWorkflowState() *DiscoveredWorkflowState {
	return &DiscoveredWorkflowState{workflowIDs: make(map[string]struct{})}
}

// Add records workflow IDs returned by list_workflows. Empty IDs are ignored.
func (s *DiscoveredWorkflowState) Add(workflowIDs ...string) {
	if s == nil {
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.workflowIDs == nil {
		s.workflowIDs = make(map[string]struct{})
	}
	for _, workflowID := range workflowIDs {
		if workflowID != "" {
			s.workflowIDs[workflowID] = struct{}{}
		}
	}
}

// Contains reports whether workflowID was returned by list_workflows.
func (s *DiscoveredWorkflowState) Contains(workflowID string) bool {
	if s == nil {
		return false
	}
	s.mu.RLock()
	defer s.mu.RUnlock()
	_, ok := s.workflowIDs[workflowID]
	return ok
}

func (e *Enricher) EnrichNotification(_ context.Context, notification *notificationv1alpha1.NotificationRequest) *notificationv1alpha1.NotificationRequest {
	workflowID := extractWorkflowID(notification.Spec.Context)
	if workflowID == "" {
		return notification
	}

	name := extractWorkflowName(notification.Spec.Context)
	if name == "" {
		return notification
	}

	enriched := notification.DeepCopy()
	enriched.Spec.Body = strings.ReplaceAll(enriched.Spec.Body, workflowID, name)
	return enriched
}

func validateSelectedWorkflow(ai *aianalysisv1.AIAnalysis) error {
	sw := ai.Status.GetRCAResult().SelectedWorkflow
	if sw == nil {
		return fmt.Errorf("AIAnalysis has no selectedWorkflow")
	}
	if sw.WorkflowID == "" {
		return fmt.Errorf("selectedWorkflow.workflowId is required")
	}
	if sw.WorkflowName == "" {
		return fmt.Errorf("selectedWorkflow.workflowName is required")
	}
	if sw.ActionType == "" {
		return fmt.Errorf("selectedWorkflow.actionType is required")
	}
	if sw.Version == "" {
		return fmt.Errorf("selectedWorkflow.version is required")
	}
	if sw.ExecutionBundle == "" {
		return fmt.Errorf("selectedWorkflow.executionBundle is required")
	}
	// Issue #1661 Change 11d (DD-WORKFLOW-018): once WorkflowExecution stops
	// resolving ExecutionEngine from DataStorage at runtime (Change 11e), an
	// empty value here would silently fall back to the wrong engine instead of
	// failing closed. Fail here, at CRD-creation time, while the cause is still
	// attributable to a specific AIAnalysis/KA selection.
	if sw.ExecutionEngine == "" {
		return fmt.Errorf("selectedWorkflow.executionEngine is required")
	}
	return nil
}

// resolved from the DS workflow catalog at selection time. Deliberately
// NOT Required: unlike WorkflowID/WorkflowName/ActionType/Version/
// ExecutionBundle (whose upstream sources guarantee non-empty values),
// AIAnalysis legitimately persists a SelectedWorkflow with this field
// empty on its partial/degenerate paths (e.g. workflow-resolution
// failure, low-confidence preservation -- see
// preservePartialSelectedWorkflow/preserveLowConfidenceWorkflow in
// pkg/aianalysis/handlers/response_processor.go) before
// RemediationOrchestrator's validateSelectedWorkflow ever runs its own
// Go-level fail-closed check. Tightening this to Required+no-omitempty
// broke exactly that: an empty string is present-but-invalid against the
// Enum, not merely "missing" (#1661 Change 12 CI regression, confirmed
// against IT-AA-344-001 and three sibling suites -- 100go.co "validate
// at the right layer": RO's runtime check, not CRD admission, is the
// correct gate here).

func PlanDiscovery(input DiscoveryPlannerInput) DiscoveryPlan {
	if !advertisedTool(input.Transcript, "list_available_actions") {
		return unresolvedDiscovery("list_available_actions is not advertised")
	}
	if hasToolResult(input.Transcript, "get_workflow") &&
		!workflowWasListed(input.Transcript, input.ExpectedWorkflowID) {
		return unresolvedDiscovery("get_workflow cannot establish discovery membership")
	}
	if !hasToolResult(input.Transcript, "list_available_actions") {
		if input.HasResourceContext && !hasToolResult(input.Transcript, "get_resource_context") {
			return planDiscoveryTool(input.Transcript, "get_resource_context", nil)
		}
		return planDiscoveryTool(input.Transcript, "list_available_actions", nil)
	}

	listResult, hasListResult := latestToolResult(input.Transcript, "list_workflows")
	if !hasListResult {
		return planDiscoveryTool(input.Transcript, "list_workflows", map[string]interface{}{
			"action_type": normalizedActionType(input.ActionType),
		})
	}

	if input.ExpectedWorkflowID == "" {
		return unresolvedDiscovery("workflow target is not configured")
	}

	membershipFound := workflowWasListed(input.Transcript, input.ExpectedWorkflowID)
	if membershipFound {
		if hasToolResult(input.Transcript, "get_workflow") {
			return DiscoveryPlan{Kind: DiscoveryComplete}
		}
		return planDiscoveryTool(input.Transcript, "get_workflow", map[string]interface{}{
			"workflow_id": input.ExpectedWorkflowID,
		})
	}

	result, valid := decodePlannerWorkflowDiscoveryResult(listResult.Payload)
	if !valid {
		return unresolvedDiscovery("invalid list_workflows result")
	}
	if result.Pagination.HasNext && result.Pagination.NextCursor != "" {
		return planDiscoveryTool(input.Transcript, "list_workflows", map[string]interface{}{
			"action_type": normalizedActionType(input.ActionType),
			"page":        "next",
			"cursor":      result.Pagination.NextCursor,
		})
	}
	return unresolvedDiscovery("workflow target was not returned by list_workflows")
}

func WorkflowDiscoveryContains(contents []GeminiContent, workflowID string) bool {
	if workflowID == "" {
		return false
	}
	for _, content := range contents {
		for _, part := range content.Parts {
			if part.FunctionResponse == nil || part.FunctionResponse.Name != openai.ToolListWorkflows {
				continue
			}
			result := decodeWorkflowDiscoveryResponse(part.FunctionResponse.Response)
			for _, workflow := range result.Workflows {
				if workflow.WorkflowID == workflowID {
					return true
				}
			}
		}
	}
	return false
}

type RemediationWorkflowStatus struct {
	// WorkflowID is the deterministic UUID derived from the workflow's content
	// hash (DeterministicUUID(ComputeContentHash(spec))). Computed locally by
	// AuthWebhook (#1661 Change 8a/8c) rather than assigned by Data Storage --
	// stable across the etcd-single-source-of-truth migration (DD-WORKFLOW-018).
	// +optional
	WorkflowID string `json:"workflowId,omitempty"`

	// ContentHash is the sha256 hex digest of the workflow's clean CRD content
	// (apiVersion/kind/metadata.name/spec), computed locally by AuthWebhook
	// (#1661 Change 8c). Lets DELETE/UPDATE flows and downstream consumers
	// verify content identity without any Data Storage round-trip.
	// +optional
	ContentHash string `json:"contentHash,omitempty"`

	// CatalogStatus reflects the workflow's lifecycle state. Always "Active"
	// once admitted -- there is no external catalog decision to defer to
	// (#1661 Change 8c, DD-WORKFLOW-018).

func (f *workflowCatalogFetcher) FetchValidator(ctx context.Context) (*parser.Validator, error) {
	fetchCtx, cancel := context.WithTimeout(ctx, 15*time.Second)
	defer cancel()

	// limit=-1: unfiltered, unbounded -- this fetch supplies catalog metadata
	// for validation. The workflow-selection context separately restricts
	// membership to IDs returned by list_workflows (Issue #2442).
	workflows, _, err := f.catalog.List(fetchCtx, nil, -1, 0)
	if err != nil {
		return nil, fmt.Errorf("workflow catalog list failed: %w", err)
	}

	ids := make([]string, 0, len(workflows))
	for i := range workflows {
		if workflows[i].WorkflowID != "" {
			ids = append(ids, workflows[i].WorkflowID)
		}
	}
	if len(ids) == 0 {
		return nil, fmt.Errorf("workflow catalog returned 0 workflows")
	}

	validator := parser.NewValidator(ids)
	schemaParser := dsschema.NewParser()
	for i := range workflows {
		w := &workflows[i]
		if w.WorkflowID == "" {
			continue
		}
		validator.SetWorkflowMeta(w.WorkflowID, buildWorkflowMeta(w, schemaParser, f.logger))
	}

	f.logger.Info("workflow catalog fetched (DD-KA-001: per-request validation)",
		"allowed_workflows", len(ids))
	return validator, nil
}

func (inv *Investigator) runWorkflowSelection(ctx context.Context, signal katypes.SignalContext, rcaSummary string, enrichData *prompt.EnrichmentData, p1Ctx *prompt.Phase1Data, llmCtx LLMInvocationContext) (result *katypes.InvestigationResult, retErr error) {
	correlationID := llmCtx.CorrelationID
	// Apply signal label overrides (target_resource_kind / target_resource_name)
	// before attaching to context. This ensures workflow discovery tools
	// (list_available_actions, list_workflows) filter by the correct component.
	// Defense-in-depth for #1064/#1065: even if enrichment resolved a container
	// kind (e.g. Namespace), the label override corrects it for tool context.
	discoveredWorkflows := katypes.NewDiscoveredWorkflowState()
	ctx = katypes.WithDiscoveredWorkflowState(ctx, discoveredWorkflows)
	overriddenSignal := ApplySignalLabelOverrides(signal)
	ctx = katypes.WithSignalContext(ctx, overriddenSignal)
	inv.logger.Info("runWorkflowSelection: post-override signal",
		"component_gvk", overriddenSignal.ComponentGVK(),
		"resource_kind", overriddenSignal.ResourceKind,
		"resource_api_version", overriddenSignal.ResourceAPIVersion,
		"correlation_id", correlationID)

	wfPromptSignal := SignalToPrompt(signal)
	LogLabelOverrideOrRejection(inv.logger, signal, wfPromptSignal, correlationID, "workflow selection")
	systemPrompt, err := inv.builder.RenderWorkflowSelection(prompt.WorkflowSelectionInput{
		Signal:                          wfPromptSignal,
		RCASummary:                      rcaSummary,
		EnrichData:                      enrichData,
		Phase1:                          p1Ctx,
		ResolvedConfidenceThreshold:     inv.resolvedConfidenceThreshold,
		InconclusiveConfidenceThreshold: inv.inconclusiveConfidenceThreshold,
	})
	if err != nil {
		return nil, fmt.Errorf("rendering workflow selection prompt: %w", err)
	}
	llmCtx.WorkflowDiscovery = newWorkflowDiscoveryAuditContext(enrichData, overriddenSignal, systemPrompt)

	messages := []llm.Message{
		{Role: "system", Content: systemPrompt},
		{Role: "user", Content: fmt.Sprintf("RCA findings: %s\n\nSelect the appropriate remediation workflow.", rcaSummary)},
	}

	loopRes, err := inv.runLLMLoop(ctx, messages, katypes.PhaseWorkflowDiscovery, llmCtx)
	if err != nil {
		return nil, err
	}
	// #1935/#1936 root cause #2 (workflow-discovery extension, #1945):
	// runLLMLoop's accumulated tool-call history must flow back into
	// messages before it feeds handleWorkflowSelectionLoopResult (and, via
	// it, retryWorkflowSubmit's two call sites and selfCorrectWorkflowSelection
	// below) — otherwise every retry/self-correction attempt operates on a
	// stale [system, user]-only slice regardless of how many
	// list_available_actions/list_workflows calls actually ran.
	if extended := loopResultMessages(loopRes); len(extended) > 0 {
		messages = extended
	}

	content, early := inv.handleWorkflowSelectionLoopResult(ctx, loopRes, rcaSummary, messages, llmCtx)
	if early != nil {
		return early, nil
	}

	result, parseErr := inv.resultParser.Parse(content)
	if parseErr != nil {
		var terminal *katypes.InvestigationResult
		content, terminal = inv.workflowSelectionRetryOrHumanReview(ctx, content, messages, rcaSummary, llmCtx, parseErr,
			fmt.Sprintf("workflow selection: LLM did not produce parseable result: %s", parseErr))
		if terminal != nil {
			return terminal, nil
		}
		// Genuine workflow selection recovered via retryWorkflowSubmit: fall
		// through into the same CatalogFetcher / selfCorrectWorkflowSelection
		// validation path below, exactly like a first-attempt success.
		// Returning it directly here would bypass catalog validation for
		// this specific retry path (#1677 follow-up hardening).
		result, parseErr = inv.resultParser.Parse(content)
		if parseErr != nil {
			return nil, fmt.Errorf("workflow selection: re-parsing retry-recovered content: %w", parseErr)
		}
	}

	// #1677 hardening (DD-WORKFLOW-019): CatalogFetcher is always configured
	// in production (cmd/kubernautagent always wires a workflowCatalogFetcher
	// backed by a LazyCatalog, ready or not) -- a nil CatalogFetcher here is
	// a test/wiring gap, not a supported "dev mode" that should silently
	// bypass validation. result.HumanReviewNeeded already true means the
	// parser/LLM itself determined no workflow selection needs validating
	// (e.g. no_matching_workflows) -- that classification is preserved
	// as-is, matching selfCorrectWorkflowSelection's own contract of only
	// running validation when there is an actual selection to validate.
	// Otherwise (a workflow WAS selected) failing closed instead of
	// returning it unvalidated mirrors selfCorrectWorkflowSelection's own
	// fetchErr handling below, so both "no fetcher configured" and "fetcher
	// configured but catalog not ready/unreachable" produce the same
	// observable outcome: human review, never silent pass-through.
	if inv.pipeline.CatalogFetcher == nil {
		if result.HumanReviewNeeded {
			return result, nil
		}
		inv.logger.Error(nil, "workflow catalog fetcher not configured, requiring human review instead of skipping validation",
			"correlation_id", correlationID)
		result.HumanReviewNeeded = true
		result.HumanReviewReason = "catalog_unavailable"
		result.Reason = "workflow catalog fetcher not configured"
		return result, nil
	}
	return inv.selfCorrectWorkflowSelection(ctx, result, content, messages, rcaSummary, correlationID, llmCtx)
}

// selfCorrectWorkflowSelection runs the catalog-validated self-correction
// loop (up to maxSelfCorrectionAttempts) for the parsed workflow-selection
// result, then applies catalog enrichment and target-alignment checks to the
// final accepted (or exhausted) result.
func (inv *Investigator) selfCorrectWorkflowSelection(ctx context.Context, result *katypes.InvestigationResult, content string, messages []llm.Message, rcaSummary, correlationID string, llmCtx LLMInvocationContext) (*katypes.InvestigationResult, error) {
	validator, fetchErr := inv.pipeline.CatalogFetcher.FetchValidator(ctx)
	if fetchErr != nil {
		inv.logger.Error(fetchErr, "workflow catalog unavailable, requiring human review")
		result.HumanReviewNeeded = true
		result.HumanReviewReason = "catalog_unavailable"
		result.Reason = fmt.Sprintf("workflow catalog unavailable: %s", fetchErr)
		return result, nil
	}
	if discoveredWorkflows, ok := katypes.DiscoveredWorkflowStateFromContext(ctx); ok {
		validator.SetDiscoveredWorkflowState(discoveredWorkflows)
	}

	state := &selfCorrectionState{content: content, messages: messages}
	correctionFn := func(r *katypes.InvestigationResult, validationErr error) (*katypes.InvestigationResult, error) {
		return inv.runSelfCorrectionAttempt(ctx, r, validationErr, state, rcaSummary, correlationID, llmCtx)
	}

	corrected, corrErr := validator.SelfCorrect(result, maxSelfCorrectionAttempts, correctionFn)
	if corrErr != nil {
		return handleSelfCorrectError(corrErr, rcaSummary)
	}
	return inv.finalizeSelfCorrection(ctx, corrected, state.attempt, correlationID, validator), nil
}

func (inv *Investigator) runSelfCorrectionAttempt(ctx context.Context, r *katypes.InvestigationResult, validationErr error, state *selfCorrectionState, rcaSummary, correlationID string, llmCtx LLMInvocationContext) (*katypes.InvestigationResult, error) {
	state.attempt++
	var errStrs []string
	if validationErr != nil {
		errStrs = []string{validationErr.Error()}
	}
	inv.emitValidationEvent(ctx, state.attempt, maxSelfCorrectionAttempts, false, errStrs, r.WorkflowID, correlationID)

	correctionMsg, renderErr := inv.renderCorrectionMessage(validationErr, state.attempt, maxSelfCorrectionAttempts)
	if renderErr != nil {
		inv.logger.Error(renderErr, "failed to render validation error template, using fallback")
		correctionMsg = fmt.Sprintf("Validation failed: %s. Please select a valid workflow.", validationErr)
	}
	state.messages = append(state.messages, llm.Message{Role: "assistant", Content: state.content})
	state.messages = append(state.messages, llm.Message{Role: "user", Content: correctionMsg})

	corrLoopRes, corrErr := inv.runLLMLoop(ctx, state.messages, katypes.PhaseWorkflowDiscovery, llmCtx)
	if corrErr != nil {
		return nil, corrErr
	}
	// #1945 (main port #1936): the nested loop's accumulated tool-call
	// history must flow back into state.messages before the next
	// self-correction attempt's request is built from it — otherwise
	// attempt N+1 is missing every tool call made during attempt N's own
	// nested loop (list_workflows, etc.), independent of the top-level
	// reassignment in runWorkflowSelection above.
	if extended := loopResultMessages(corrLoopRes); len(extended) > 0 {
		state.messages = extended
	}
	return inv.classifySelfCorrectionLoopResult(corrLoopRes, r, state, rcaSummary)
}

type ListWorkflowsInput struct {
	// Kind filters by Kubernetes resource kind (e.g. "Deployment", "Pod"),
	// mapped onto WorkflowSearchFilters.Component.
	Kind string `json:"kind,omitempty"`
}

type ListWorkflowsTool struct {
	catalog WorkflowLister
}

func (t *ListWorkflowsTool) Handle(ctx context.Context, input ListWorkflowsInput) (ListWorkflowsOutput, error) {
	if t.catalog == nil {
		return ListWorkflowsOutput{}, ErrCodeInternalError.WithDetail("reason", "workflow catalog unavailable")
	}

	filters := &models.WorkflowSearchFilters{Component: input.Kind}
	workflows, _, err := t.catalog.List(ctx, filters, defaultListWorkflowsLimit, 0)
	if err != nil {
		return ListWorkflowsOutput{}, fmt.Errorf("listing workflows: %w", err)
	}

	summaries := make([]CatalogWorkflowSummary, 0, len(workflows))
	for i := range workflows {
		w := &workflows[i]
		summaries = append(summaries, CatalogWorkflowSummary{
			ID:          w.WorkflowID,
			Name:        w.WorkflowName,
			Description: w.Description.What,
			Kind:        w.ActionType,
		})
	}

	return ListWorkflowsOutput{Workflows: summaries, Count: len(summaries)}, nil
}

type Validator struct {
	allowedWorkflows    map[string]struct{}
	catalogMeta         map[string]WorkflowMeta
	discoveredWorkflows *katypes.DiscoveredWorkflowState
}

// SetDiscoveredWorkflowState attaches the live workflow-discovery membership
// for the current selection context. The pointer is intentional: a
// self-correction retry may call list_workflows and expand membership after
// validation has started.
func (v *Validator) SetDiscoveredWorkflowState(state *katypes.DiscoveredWorkflowState) {
	v.discoveredWorkflows = state
}

// maxPatternLength caps regex pattern length to prevent ReDoS from excessively
// long patterns in workflow schemas. Patterns exceeding this are treated as
// invalid and skipped (warning emitted at validation time).
const maxPatternLength = 1024

// compileParameterPatterns pre-compiles regex patterns from workflow parameter
// definitions. Invalid or oversized patterns are silently skipped — they'll
// produce a warning at validation time via the fallback path.

func (v *Validator) GetWorkflowMeta(workflowID string) (WorkflowMeta, bool) {
	m, ok := v.catalogMeta[workflowID]
	return m, ok
}

// IsAllowed reports whether workflowID is present in the catalog allowlist and,
// when discovery state is attached, was returned by list_workflows in the
// current selection context. This
// is the same membership test Validate applies to workflow_id, exposed here
// so callers outside Validate (e.g. enrichFromCatalog's Issue #1711 guard)
// can distinguish "unresolvable ID" from "resolvable ID with no registered
// WorkflowMeta" -- the latter occurs only in test fixtures that populate the
// allowlist without a matching SetWorkflowMeta call; production always sets
// both from the same catalog-fetch loop (see dsCatalogFetcher.FetchValidator).
func (v *Validator) IsAllowed(workflowID string) bool {
	if _, ok := v.allowedWorkflows[workflowID]; !ok {
		return false
	}
	return v.discoveredWorkflows == nil || v.discoveredWorkflows.Contains(workflowID)
}

func (t *listActionsTool) Execute(ctx context.Context, args json.RawMessage) (string, error) {
	signal, err := signalFromContext(ctx, "listing action types")
	if err != nil {
		return "", err
	}

	var a struct {
		Page   string `json:"page"`
		Cursor string `json:"cursor"`
	}
	if err := json.Unmarshal(args, &a); err != nil {
		return "", fmt.Errorf("parsing args: %w", err)
	}

	filters := filtersFromSignal(signal)
	logr.FromContextOrDiscard(ctx).V(1).Info("list_available_actions: resolved component",
		"component", filters.Component, "remediation_id", signal.RemediationID)

	offset, limit := 0, defaultPaginationLimit
	if a.Page != "" && a.Cursor != "" {
		offset, limit = decodeCursor(a.Cursor)
	}

	if t.catalog == nil {
		return "", fmt.Errorf("listing action types: workflow catalog unavailable")
	}

	start := time.Now()
	entries, totalCount, err := t.catalog.ListActions(ctx, filters, offset, limit)
	durationMs := time.Since(start).Milliseconds()
	if err != nil {
		return "", fmt.Errorf("listing action types: %w", err)
	}

	t.emitAuditEvent(ctx, filters, totalCount, durationMs)

	resp := models.ActionTypeListResponse{
		ActionTypes: entries,
		Pagination: models.PaginationMetadata{
			TotalCount: totalCount,
			Offset:     offset,
			Limit:      limit,
			HasMore:    offset+limit < totalCount,
		},
	}
	data, err := json.Marshal(resp)
	if err != nil {
		return "", fmt.Errorf("marshaling action types response: %w", err)
	}
	return string(transformPagination(data)), nil
}

func convertWorkflowsToDiscoveryEntries(workflows []models.RemediationWorkflow) []models.WorkflowDiscoveryEntry {
	discoveryEntries := make([]models.WorkflowDiscoveryEntry, 0, len(workflows))
	for _, wf := range workflows {
		entry := models.WorkflowDiscoveryEntry{
			WorkflowID:      wf.WorkflowID,
			WorkflowName:    wf.WorkflowName,
			Name:            wf.Name,
			Description:     wf.Description,
			Version:         wf.Version,
			ExecutionEngine: string(wf.ExecutionEngine),
		}
		if wf.SchemaImage != nil {
			entry.SchemaImage = *wf.SchemaImage
		}
		if wf.ExecutionBundle != nil {
			entry.ExecutionBundle = *wf.ExecutionBundle
		}
		if wf.ServiceAccountName != nil {
			entry.ServiceAccountName = *wf.ServiceAccountName
		}
		discoveryEntries = append(discoveryEntries, entry)
	}
	return discoveryEntries
}

// matches workflowID, or (nil, nil) if none exists -- matching the retired
// Postgres repository's not-found convention. Lookup is cluster-wide by the
// content-hash identity (DD-WORKFLOW-018), not by name: this is Step 3 of
// the discovery protocol.
func (c *Cache) GetWorkflowByID(ctx context.Context, workflowID string) (*rwv1alpha1.RemediationWorkflow, error) {
	var list rwv1alpha1.RemediationWorkflowList
	if err := c.reader.List(ctx, &list, client.MatchingFields{workflowIDFieldIndex: workflowID}); err != nil {
		return nil, fmt.Errorf("failed to get RemediationWorkflow by workflow_id %s: %w", workflowID, err)
	}
	if len(list.Items) == 0 {
		return nil, nil //nolint:nilnil // intentional "not found, no error" cache-layer contract, see doc comment above
	}
	return &list.Items[0], nil
}

// ListWorkflowsByActionType returns every RemediationWorkflow CRD whose
// spec.actionType matches actionType, using the indexed field lookup instead
// of a full scan.

func (c *Catalog) ListWorkflowsByActionType(ctx context.Context, actionType string, filters *models.WorkflowDiscoveryFilters, offset, limit int) ([]models.RemediationWorkflow, int, error) {
	return c.listWorkflowsByActionTypeFromCache(ctx, actionType, filters, offset, limit)
}

// Returns ErrNotFound if the workflow doesn't exist OR exists but doesn't match
// the context (security gate) — DD-WORKFLOW-016: the two cases are
// deliberately not distinguished to prevent information leakage.
// This is Step 3 of the discovery protocol.
func (c *Catalog) GetWorkflowWithContextFilters(ctx context.Context, workflowID string, filters *models.WorkflowDiscoveryFilters) (*models.RemediationWorkflow, error) {
	// If no context filters, fall back to simple GetByID
	if filters == nil || !filters.HasContextFilters() {
		return c.GetByID(ctx, workflowID)
	}

	return c.getWorkflowWithContextFiltersFromCache(ctx, workflowID, filters)
}

