func validateSelectedWorkflow(ai *aianalysisv1.AIAnalysis) error {
	sw := ai.Status.GetRCAResult().SelectedWorkflow
	if sw == nil {
		return fmt.Errorf("AIAnalysis has no selectedWorkflow")
	}
	if sw.WorkflowID == "" {
		return fmt.Errorf("selectedWorkflow.workflowId is required")
	}
	if sw.WorkflowName == "" {
		return fmt.Errorf("selectedWorkflow.workflowName is required")
	}
	if sw.ActionType == "" {
		return fmt.Errorf("selectedWorkflow.actionType is required")
	}
	if sw.Version == "" {
		return fmt.Errorf("selectedWorkflow.version is required")
	}
	if sw.ExecutionBundle == "" {
		return fmt.Errorf("selectedWorkflow.executionBundle is required")
	}
	// Issue #1661 Change 11d (DD-WORKFLOW-018): once WorkflowExecution stops
	// resolving ExecutionEngine from DataStorage at runtime (Change 11e), an
	// empty value here would silently fall back to the wrong engine instead of
	// failing closed. Fail here, at CRD-creation time, while the cause is still
	// attributable to a specific AIAnalysis/KA selection.
	if sw.ExecutionEngine == "" {
		return fmt.Errorf("selectedWorkflow.executionEngine is required")
	}
	return nil
}

func ResolveWorkflow(
	ctx context.Context,
	reader client.Reader,
	overrideSpec *remediationv1.WorkflowOverride,
	aiWorkflow *aianalysisv1.SelectedWorkflow,
	namespace string,
) (*aianalysisv1.SelectedWorkflow, bool, error) {
	logger := ctrl.LoggerFrom(ctx).WithValues(
		"originalWorkflowID", aiWorkflow.WorkflowID,
	)

	if overrideSpec == nil {
		return aiWorkflow, false, nil
	}

	logger = logger.WithValues(
		"override.workflowName", overrideSpec.WorkflowName,
		"override.hasParams", overrideSpec.Parameters != nil,
	)

	resolved := aiWorkflow.DeepCopy()

	if overrideSpec.WorkflowName != "" {
		rw := &remediationworkflowv1.RemediationWorkflow{}
		err := reader.Get(ctx, client.ObjectKey{Name: overrideSpec.WorkflowName, Namespace: namespace}, rw)
		if err != nil {
			if apierrors.IsNotFound(err) {
				return nil, false, &overrideNotFoundError{
					workflowName: overrideSpec.WorkflowName,
					namespace:    namespace,
					cause:        err,
				}
			}
			return nil, false, fmt.Errorf("failed to lookup RemediationWorkflow %q in namespace %q: %w",
				overrideSpec.WorkflowName, namespace, err)
		}

		// G2: field mapping from the override-target RW CRD onto the shared
		// sharedtypes.WorkflowSnapshot embed. Issue #1661 Change 12 adds
		// WorkflowName (a direct rw.Name field, trivially fixable) to the 8
		// already mapped here. Dependencies/Resources/DeclaredParameterNames
		// remain intentionally NOT remapped -- they're schema-derived
		// (parsed by KA from the OCI execution bundle), and this override
		// path only has CRD access, not KA's schema-parsing pipeline, so
		// they stay stale copies from the original AI-selected workflow
		// (aiWorkflow.DeepCopy() above). Pre-existing latent gap, tracked
		// separately, not addressed here -- see Change 12 plan's "Open
		// design question".
		resolved.WorkflowID = rw.Status.WorkflowID
		resolved.WorkflowName = rw.Name
		resolved.ActionType = rw.Spec.ActionType
		resolved.Version = rw.Spec.Version
		resolved.ExecutionBundle = rw.Spec.Execution.Bundle
		resolved.ExecutionBundleDigest = rw.Spec.Execution.BundleDigest
		resolved.ExecutionEngine = rw.Spec.Execution.Engine
		resolved.EngineConfig = rw.Spec.Execution.EngineConfig
		resolved.ServiceAccountName = rw.Spec.Execution.ServiceAccountName
		// Confidence preserved from aiWorkflow (AI's assessment, not overridden)
	}

	if overrideSpec.Rationale != "" {
		resolved.Rationale = overrideSpec.Rationale
	}

	if overrideSpec.Parameters != nil {
		resolved.Parameters = overrideSpec.Parameters
	}

	logger.Info("Workflow override resolved",
		"resolvedWorkflowID", resolved.WorkflowID,
	)

	return resolved, true, nil
}

// resolved from the DS workflow catalog at selection time. Deliberately
// NOT Required: unlike WorkflowID/WorkflowName/ActionType/Version/
